window.TEXTP["83.17"] = [{"n":341,"head":"УБЕЖДЕНИЯ ПРИВЕРЖЕНЦЕВ СУННЫ И ЕДИНОЙ ОБЩИНЫ","side":"c","blocks":[["p","[624] Сура «аль-Исра», аят 3."],["p","[625] Сура «аль-Фуркан», аят 1."],["p","[626] Сура «Сод», аят 45."],["p","[627] Сура «Сод», аят 17."],["p","[628] Сура «Сод», аят 30."],["p","[629] Сура «аз-Зухруф», аят 59."],["p","[630] Автор книги приводит этот отрывок из стихотворения в качестве дополнительного доказательства из арабского языка и жизни арабов, после того как он привел множество аятов Корана."],["p","[631] Говорят, что эти строки принадлежат Кады ′Ияду. А Аллах знает лучше!"],["p","[632] Сура «аль-А′раф», аят 158."],["p","[633] Сура «аль-А′раф», аят 158."],["p","[634] Сура «аль-А′раф», аят 158."],["p","[635] Сура «аль-Ахзаб», аят 40."],["p","[636] Сура «Али ′Имран», аят 19."],["p","[637] Сура «аль-Маида», аят 3. Ибн «Аббас, да будет доволен Аллах им и его отцом, сказал в отношении этого аята: «Аллах известил Своего Пророка (да благословит его Аллах и приветствует) и верующих о том, что Он довел до совершенства веру для них и что они никогда не будут нуждаться в ее дополнении. Аллах завершил веру, и не будет у нее недостатка, Он одобрил ее, и не будет когда-либо недовольным ею». См. «Тафсир ат-Табари», 9/518, «Тафсир Ибн Касир», 2/12."],["p","[638] Сура «Али ′Имран», аят 85."],["p","[639] Муслим, 1718, со слов ′Аиши, да будет доволен ею Аллах. Имам Ибн Дакык аль-«Ид сказал: <i>«Языковеды говорили, что слово «отвергнуто» означает: недействительно!»</i> См. «Шарх аль-арба’ин», 24."],["p","[640] Сура «Али ′Имран», аят 85."],["p","[641] Сура «аш-Шу′ара», аят 105."],["p","[642] Сура «ан-Ниса», аяты 150—151."],["p","[643] Сура «ас-Сафф», аят 6."]],"notes":[]},{"n":342,"head":"МУХАММАД ИБН САЛИХ ИБН 'УСЕЙМИН","side":"c","blocks":[["p","[644] Передают со слов Джубайра ибн Мут‘има (да будет доволен им Аллах), что Посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«У меня есть пять имён: я — Мухаммад и Ахмад, и я — аль-Махи, посредством которого Аллах сотрёт неверие, и я — аль-Хашир, у ног которого будут собраны люди, и я — аль-«Акиб».</i></b> аль-Бухари, 3532; Муслим, 2354. «Аль-Махи» — стирающий, а «Аль-Хашир» — собирающий. Имеется в виду либо то, что в День воскресения Пророк (да благословит его Аллах и приветствует) окажется на месте сбора первым, либо то, что в этом мире он являлся последним пророком, вокруг которого соберутся люди. «Аль-«Акиб» — идущий последним. Имеется в виду, что после пророка Мухаммада (да благословит его Аллах и приветствует) других пророков уже не будет."],["p","[645] Сура «аш-Шу′ара», аят 105."],["p","[646] Сура «ан-Ниса», аяты 150—151."],["p","[647] Сура «аль-Бакара», аят 85."],["p","[648] Сура «аль-Ахзаб», аят 40."],["p","[649] Первый из четырёх праведных халифов. Его звали Абу Бакр «Абдуллах ибн «Усман ибн «Амир ибн Амр ибн Ка'б ибн Са'д ибн Тайм ибн Мурра ибн Ка'б ибн Люайй ибн Галиб ибн Фахр ат-Тейми аль-Кураши. У них с Пророком (да благословит его Аллах и приветствует) был общий предок — Мурра ибн Ка'б. Его мать звали Умм уль-Хайр Сальма бинт Сахр. Абу Бакр родился на два года позже Посланника Аллаха (да благословит его Ал-лах и приветствует). Он отличался благим нравом и вёл достойную жизнь. Он был состоятельным, помогал людям и подавал нуждающимся. Абу Бакр был другом Мухаммада (да благословит его Аллах и приветствует) ещё до начала пророческой миссии. Абу Бакр первым внял его призыву и уверовал в него. Затем он призвал к исламу своих братьев и друзей из племени Курейш, и на его призыв откликнулись несколько человек. Когда язычники начали истязать своих рабов, принявших ислам, Абу Бакр выкупал их и освобождал. А когда Аллах разрешил Пророку (да благословит его Аллах и приветствует) совершить переселение в Медину, Абу Бакр сопровождал его. Абу Бакр выдал свою дочь"]],"notes":[]},{"n":343,"head":"УБЕЖДЕНИЯ ПРИВЕРЖЕНЦЕВ СУННЫ И ЕДИНОЙ ОБЩИНЫ","side":"c","blocks":[["c","«Аишу замуж за Посланника Аллаха (да благословит его Аллах и приветствует). Абу Бакр сопровождал Посланника Аллаха (да благословит его Аллах и приветствует) во многих походах, а в последнем его походе на Табук Абу Бакр нёс знамя. А в девятом году от хиджры Посланник Аллаха (да благословит его Ал-лах и приветствует) велел ему совершить хадж с людьми. Во время своей предсмертной болезни Посланник (да благословит его Аллах и приветствует) велел ему совершать молитвы с людьми, и это самый веский довод в пользу того, что именно Абу Бакр должен был стать халифом мусульман после него. У него был сын «Абдуллах, дочь «Аиша, сын Мухаммад. У Абу Бакра также была дочь Умм Кульсум, которая родилась после его смерти."],["p","[650] «Умар ибн уль-Хаттаб ибн Нуфейль ибн «Абд уль-«Узза ибн Риях ибн «Абдуллах ибн Курт ибн Разах ибн Ади ибн Ка'б ибн Люайй аль-′Адави аль-Кураши. У них с Посланником Аллаха (да благословит его Аллах и приветствует) был общий предок — Ка'б ибн Люайй. Один из величайших сподвижников и один из десяти обрадованных благой вестью о Рае. Носил прозвище аль-Фарук. Известен своей богобоязненностью, строгостью и справедливостью. Дочь Умара Хафса была одной из жён Пророка (да благословит его Аллах и приветствует). Второй праведный халиф. Правил десять лет. Учредил канцелярии и ввёл летоисчисление по хиджре. Был смертельно ранен отравленным кинжалом рабом-огнепоклонником Абу Люлюа во время совершения утренней молитвы 26 числа месяца зу-ль-хиджжа 23 г. х."],["p","[651] «Усман ибн «Аффан ибн Абу ль-«Ас ибн Умайя ибн Абд Шамс ибн «Абд Манаф аль-Умави аль-Кураши. Он родился через пять лет после Посланника Аллаха (да благословит его Ал-лах и приветствует). Он был известен своим благонравием и стыдливостью и прожил достойную жизнь. После начала пророческой миссии Мухаммада (да благословит его Аллах и приветствует) он принял ислам одним из первых, когда его призвал Абу Бакр ас-Сыддик. Посланник (да благословит его Аллах и приветствует) выдал за него свою дочь Рукайю. Когда язычники"]],"notes":[]},{"n":344,"head":"МУХАММАД ИБН САЛИХ ИБН 'УСЕЙМИН","side":"c","blocks":[["c","начали притеснять мусульман, он переселился вместе с женой в Эфиопию. Затем он вернулся в Мекку, после чего переселился в Медину вместе с женой и остальными мусульманами. Он участвовал во всех сражениях и военных походах Посланника Аллаха (да благословит его Аллах и приветствует), за исключением битвы при Бадре, во время которой он был занят уходом за заболевшей женой. Она скончалась вскоре после победы мусульман в этой битве. Посланник Аллаха (да благословит его Ал-лах и приветствует) выделил ему долю военной добычи и выдал за него свою вторую дочь Умм Кульсум. После кончины Посланника Аллаха (да благословит его Аллах и приветствует) «Усман был верным помощником двух праведных халифов. После гибели «Умара большинство участников совета высказались за то, чтобы он стал халифом. Он был прекрасным правителем. Однако в конце его правления началась смута. Халифат дрогнул, и вскоре «Усман был убит заговорщиками. В то время ему было уже более восьмидесяти лет."],["p","[652] «Али ибн Аби Талиб был первым ребёнком, принявшим ислам, и впоследствии стал четвёртым праведным халифом. Правил с 35 по 40 г. х. Он приходился Посланнику Аллаха (да благословит его Аллах и приветствует) двоюродным братом и зятем. Он женился на его дочери Фатыме в месяце рамадан 2 г. х., когда ему было 20 лет. Он принимал участие во всех сражениях и военных походах Посланника Аллаха (да благословит его Аллах и приветствует), кроме похода на Табук, во время которого он управлял Мединой. Во время утренней молитвы в Куфе он был смертельно ранен злоумышленником по имени «Абд ур-Рахман ибн Мульджам. Скончался в пятницу, 17 числа месяца рамадан 40 г. х."],["p","[653] «Абдуллах ибн «Умар, да будет доволен Аллах им и его отцом, передаёт: <i>«При жизни Посланника Аллаха (да благословит его Аллах и приветствует) мы говорили, что самый достойный в общине Пророка</i> (да благословит его Аллах и приветствует) <i>после него — Абу Бакр, затем — «Умар, затем — «Усман, да будет Аллах доволен ими всеми».</i> Абу Дауд, 4628."]],"notes":[]},{"n":345,"head":"УБЕЖДЕНИЯ ПРИВЕРЖЕНЦЕВ СУННЫ И ЕДИНОЙ ОБЩИНЫ","side":"c","blocks":[["c","Мухаммад ибн уль-Ханафийя передаёт: <i>«Я сказал своему отцу (′Али ибн Аби Талибу): «Скажи, кто является лучшим из людей после Посланника Аллаха (да благословит его Аллах и приветствует)?» Он ответил: «Абу Бакр». Я спросил: «А после него кто?» Он ответил: ««Умар». И я испугался, что, если спрошу: «А после него кто?», — он скажет: ««Усман». Поэтому я спросил: «А потом ты?» Он сказал в ответ: «Я — всего лишь один из мусульман».</i> Аль-Бухари, 3671; Абу Дауд, 4629, Ибн Маджа, 106. Это явное указание на то, что «Али, как и остальные сподвижники, считал, что лучшим человеком после Пророка (да благословит его Аллах и приветствует) был Абу Бакр. «Абдуллах ибн «Умар, да будет доволен Аллах им и его отцом, передаёт: <i>«Во времена Пророка</i> (<i>да благословит его Аллах и приветствует) мы говорили, что не станем никого приравнивать к Абу Бакру, за которым следовал «Умар, а потом «Усман. Что же касается остальных сподвижников, то никого из них мы не считали достойнее других».</i> Аль-Бухари, 3655; Абу Дауд, 4627, ат-Тирмизи, 3707. Имелись в виду пожилые и зрелые люди, с которыми Посланник Аллаха (да благословит его Аллах и приветствует) советовался в важных делах: по большей части это были уже зрелые или даже пожилые люди с большим жизненным опытом. Что же касается «Али, то он в то время был совсем молодым, и «Абдуллах ибн «Умар не упомянул его именно по этой причине, а не для того, чтобы скрыть его достоинства. Его достоинства известны, и их не отрицал ни Ибн «Умар, ни другие сподвижники."],["p","[654] Аль-Бухари, 3662; Муслим, 2384, со слов ′Амра ибн уль-′Аса (да будет доволен им Аллах)."],["p","[655] Аль-Бухари, 3654; Муслим, 2382, со слов Абу Са′ида аль-Худри (да будет доволен им Аллах)."],["p","[656] Аль-Бухари, 1622; Муслим, 1347, со слов Абу Хурейры (да будет доволен им Аллах)."],["p","[657] Аль-Бухари, 466; Муслим, 2382, со слов Абу Са′ида аль-Худри (да будет доволен им Аллах)."],["p","[658] Аль-Бухари, 3659; Муслим, 2386."]],"notes":[]},{"n":346,"head":"МУХАММАД ИБН САЛИХ ИБН 'УСЕЙМИН","side":"c","blocks":[["p","[659] Посланник Аллаха (да благословит его Аллах и приветствует) имел в виду, что найдутся желающие стать халифом, которые будут заявлять, что достойны власти больше других."],["p","[660] Аль-Бухари, 7217; Муслим, 2387."],["p","[661] История назначения «Усмана ибн «Аффана халифом приводится в «Сахихе» аль-Бухари. Аль-Бухари приводит длинный хадис о гибели «Умара. В нём упоминается о том, что ему сказали: <i>«О повелитель верующих, дай нам наставление и назначь преемника».</i> «Умар сказал: <i>«Я не знаю никого, кто был бы достоин этого больше, чем эти несколько человек, которыми Посланник Аллаха</i> (да благословит его Аллах и приветствует) <i>был доволен до самой своей смерти».</i> И он назвал «Али, «Усмана, аз-Зубайра, Са‘да, Тальху и «Абд ур-Рахмана ибн «Ауфа. «Умар сказал: <i>« (Мой сын) «Абдуллах ибн «Умар будет свидетелем для вас, однако сам он не должен получать никакой власти. Если к власти придёт Са‘д, это будет хорошо, а если нет, пусть тот из вас, кто станет править, обращается к нему за помощью и советом. Поистине, я отстранял его не по причине слабости или вероломства».</i> Ранее «Умар снял Са‘да ибн Аби Уаккаса с должности наместника Куфы. После погребения избранные им шесть человек собрались, и «Абд ур-Рахман ибн «Ауф сказал: <i>«Вручите правление собой трём из вас».</i> Аз-Зубайр сказал: <i>«Вручаю себя «Али».</i> Тальха сказал: <i>«Вручаю себя «Усману».</i> А Са‘д сказал: <i>«Вручаю себя «Абд ур-Рахману ибн «Ауфу».</i> Таким образом, три кандидата отказались претендовать на пост халифа в пользу остальных трёх кандидатов. Остались «Али, «Усман и «Абд ур-Рахман ибн «Ауф. «Абд ур-Рахман сказал «Усману и «Али: <i>«Кто из вас согласится, чтобы мы поручили ему это дело и он отвечал перед Аллахом и исламом?»</i> Они молчали. Тогда «Абд ур-Рахман сказал: <i>«Вы хотите поручить это дело мне? Клянусь Аллахом… Я сам должен выбрать лучшего из вас?»</i> Они ответили: <i>«Да».</i> Тогда он взял за руку «Али и сказал: <i>«Ты — родственник Посланника Аллаха</i> (да благословит его Аллах и приветствует) <i>и принял ислам среди первых, и тебе об этом известно. Если я выберу тебя, ты обязан перед Аллахом править справедливо. А если я выберу</i>"]],"notes":[]},{"n":347,"head":"УБЕЖДЕНИЯ ПРИВЕРЖЕНЦЕВ СУННЫ И ЕДИНОЙ ОБЩИНЫ","side":"c","blocks":[["c","<i>«Усмана, ты должен слушать его и подчиняться ему».</i> Потом он остался наедине с «Усманом и сказал ему то же самое. Взяв с них это обещание, он сказал: <i>«Подними руку, о «Усман!»</i> — и присягнул ему. «Али тоже присягнул ему, а потом собрались обитатели дома и присягнули ему. Это — история избрания «Усмана ибн «Аффана, которая приводится в «Сахихе» аль-Бухари. В других достоверных версиях этой истории упоминаются некоторые подробности этого события. Например, сообщается, что «Абд ур-Рахман ибн «Ауф в течение трёх дней опрашивал мухаджиров и ансаров, чтобы выяснить, кого они желают видеть своим правителем. Он сказал: <i>«Клянусь Аллахом, я не пропустил ни одного дома мухаджиров и ансаров. Я опросил всех и обнаружил, что они не знают равных «Усману».</i> Передал аль-Бухари."],["p","[662] После смерти «Усмана ибн «Аффана оставшиеся в Медине сподвижники присягнули ′Али ибн Аби Талибу, потому что в то время не было лучшего кандидата на пост халифа, чем он. После гибели «Усмана никто не заявлял о своём желании или праве стать халифом. И ′Али ибн Аби Талиб не стремился к власти, поэтому он согласился стать правителем только после того, как увидел, что оставшиеся в Медине сподвижники настаивают на этом, поскольку были все основания опасаться дальнейшего распространения и усиления смуты."],["p","[663] Ахмад, 5/220; Абу Дауд, 4646; ат-Тирмизи, 2226. Посланник Аллаха (да благословит его Аллах и приветствует) сказал в этом хадисе: <i>«Будут править преемники пророка в течение тридцати лет, а потом Аллах дарует власть, кому пожелает».</i> Са‘ид (передатчик хадиса) передаёт: «Сафина сказал мне: <i>«Посчитай: Абу Бакр два года, «Умар десять, «Усман двенадцать и «Али столько-то».</i>"],["p","[664] Му‘авия ибн Аби Суфьян. Принял ислам вместе со своим отцом Абу Суфьяном Сахром ибн Харбом после покорения Мекки. «Умар ибн аль-Хаттаб назначил его наместником Шама после смерти его брата Язида ибн Абу Суфьяна. Он оставался наместником Шама вплоть до времён правления «Али ибн Абу Талиба. После того как аль-Хасан ибн «Али добровольно отказался"]],"notes":[]},{"n":348,"head":"МУХАММАД ИБН САЛИХ ИБН 'УСЕЙМИН","side":"c","blocks":[["c","от власти в 40 г. х., он стал правителем. Скончался в 60 г. х. в возрасте 78 лет."],["p","[665] В данном случае под словом «сын» следует понимать «потомок», так как аль-Хасан являлся внуком Пророка (да благословит его Аллах и приветствует)."],["p","[666] Аль-Бухари, 2704, со слов Абу Бакры (да будет доволен им Аллах)."],["p","[667] Ахмад, 3/3; ат-Тирмизи, 3768, со слов Абу Са′ида аль-Худри (да будет доволен им Аллах)."],["p","[668] См. «Маджму′ уль-фатауа», 3/153."],["p","[669] Ахмад, 5/63; ат-Тирмизи, 3701, со слов ′Абд ур-Рахмана ибн Самуры (да будет доволен им Аллах)."],["p","[670] Аль-Бухари в подвешенном состоянии (му′алляк), 3/109. А также Ахмад, 1/74—75; ат-Тирмизи, 3703; ан-Насаи, 3608."],["p","[671] Прибыв в Медину, Посланник Аллаха (да благословит его Аллах и приветствует) обнаружил, что в ней очень мало пресной воды и единственным колодцем с хорошей водой был колодец Рума. Из этого колодца можно было брать воду только за плату. Затем ′Усман ибн ′Аффан (да будет доволен им Аллах) выкупил этот колодец и отдал его в пользование мусульман."],["p","[672] То есть пока они не примут ислам."],["p","[673] Такие верблюды являлись самым ценным имуществом арабов в те времена."],["p","[674] Аль-Бухари, 2942; Муслим, 2406."],["p","[675] Увейн ибн ′Амир аль-Карни — жил во времена Посланника Аллаха (да благословит его Аллах и приветствует), но не смог приехать к нему из-за своей матери, к которой он проявлял великое благочестие."],["p","[676] Муслим, 2542."],["p","[677] Сура «Али ′Имран», аят 110."],["p","[678] Сура «аль-Маида», аят 79."],["p","[679] Аль-Бухари, 2652; Муслим, 2533."],["p","[680] Эти слова передал Ибн уль-Каййим в «Иджтима′ ульджуюш иль-ислямия», 2/218."]],"notes":[]},{"n":349,"head":"УБЕЖДЕНИЯ ПРИВЕРЖЕНЦЕВ СУННЫ И ЕДИНОЙ ОБЩИНЫ","side":"c","blocks":[["p","[681] Аль-Хаджжадж ибн Юсуф ас-Сакафи — прославившийся своей жестокостью наместник Oмеййядского халифа."],["p","[682] Аль-Бухари, 7068."],["p","[683] Аль-Бухари, 7460; Муслим, 1037."],["p","[684] Передают, что «Амр ибн уль-«Ас (да будет доволен им Аллах) рассказывал, что слышал, как Посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Если судья вынесет решение, проявив усердие, и его решение окажется правильным, ему полагается двойная награда; если же он вынесет решение, проявив усердие, и ошибётся, то ему полагается одна награда».</i> </b>Бухари, 7352; Муслим, 1716."],["p","[685] Сура «аль-Хадид», аят 10."],["p","[686] Сура «аль-Хашр», аят 10."],["p","[687] Аль-Бухари, 3673; Муслим, 2541, со слов Абу Са′ида аль-Худри (да будет доволен им Аллах)."],["p","[688] Сура «аль-Хашр», аяты 8—10."],["p","[689] Муслим, 8; Абу Дауд, 4695; ан-Насаи, 4990; Ахмад, 1/51; Ибн Хузейма, 2504; ат-Таялиси, 21; аль-Бейхакы в «Сунан аль-кубра», 10/203, со слов ′Умара ибн уль-Хаттаба. Также этот хадис передали аль-Бухари и Муслим со слов Абу Хурейры."],["p","[690] Сура «аз-Зумар», аят 68."],["p","[691] Сура «аль-Анбия», аят 104."],["p","[692] Муслим, 770, со слов ′Аиши, да будет доволен ею Ал-лах."],["p","[693] Сура «аз-Зумар», аят 68."],["p","[694] С этим вопросом обратились к Абу Хурейре (да будет доволен им Аллах) те, кто услышал от него этот хадис."],["p","[695] То есть я не могу точно утверждать, о чем именно идет речь: о днях, месяцах или годах."],["p","[696] Аль-Бухари, 4814; Муслим, 2955."],["p","[697] Сура «аль-Анбия», аят 104."],["p","[698] Сообщается, что ′Аиша, да будет доволен ею Аллах, рассказывала: <i>«Я слышала, как Посланник Аллаха (да благословит его Аллах и приветствует) говорил:</i> <b><i>„Люди будут собраны (пред Аллахом) босыми, нагими и необрезанными“.</i></b> <i>Тогда я спросила</i>"]],"notes":[]},{"n":350,"head":"МУХАММАД ИБН САЛИХ ИБН 'УСЕЙМИН","side":"c","blocks":[["c","<i>:</i> <b><i>« (Неужели) мужчины и женщины (будут стоять) вместе и смотреть друг на друга?»</i></b> <i>(Пророк (да благословит его Аллах и приветствует)) ответил:</i> <b><i>«Дело (в Тот День) будет настолько суровым, что их не будет интересовать это!»</i></b> В другой версии сказано: <b><i>«Дело (в Тот День) будет настолько суровым, что они не станут смотреть друг на друга».</i></b> Хафиз аль-Мунзири сказал: <i>«Этот хадис передали аль-Бухари, Муслим, ан-Насаи и Ибн Маджа».</i>"],["p","[699] Сура «′Абаса», аят 37."],["p","[700] Сура «аль-Иншикак», аяты 7—12."],["p","[701] Сура «аль-Исра», аяты 13—14."],["p","[702] Сура «Каф», аят 18."],["p","[703] Сура «аз-Зухруф», аят 80."],["p","[704] Сура «аль-Кахф», аят 49."],["p","[705] Сура «аль-Исра», аяты 13—14."],["p","[706] Сура «аль-Иншикак», аят 7."],["p","[707] Сура «аль-Иншикак», аят 10."],["p","[708] Сура «аль-Хакка», аят 25."],["p","[709] Аль-Бухари, 4685; Муслим, 2768."],["p","[710] Аль-Бухари, 6536; Муслим, 2876, со слов ′Аиши."],["p","[711] Сура «аз-Зальзаля», аяты 7—8."],["p","[712] Сура «аль-Муминун», аяты 102—104."],["p","[713] Сура «аль-Ан′ам», аят 160."],["p","[714] Сура «аль-Анбия», аят 47."],["p","[715] Аль-Бухари, 6406; Муслим, 2694, со слов Абу Хурейры (да будет доволен им Аллах)."],["p","[716] Ахмад, 1/114, 1/420."],["p","[717] Сура «аль-Кахф», аят 105."],["p","[718] Аль-Бухари, 6406; Муслим, 2694, со слов Абу Хурейры (да будет доволен им Аллах)."],["p","[719] Ахмад, 2/213; ат-Тирмизи, 2639; Ибн Маджа, 4300."],["p","[720] Сура «аль-Муминун», аяты 102—104."],["p","[721] Сура «аль-Ан′ам», аят 160."],["p","[722] В достоверном хадисе сказано: <b><i>«Поистине, Аллах записал благие и скверные поступки, а затем разъяснил это: «Кто</i></b>"]],"notes":[]},{"n":351,"head":"УБЕЖДЕНИЯ ПРИВЕРЖЕНЦЕВ СУННЫ И ЕДИНОЙ ОБЩИНЫ","side":"c","blocks":[["c","<b><i>вознамерился совершить благой поступок, но не совершил его, тому Аллах запишет у Себя совершение полноценного благого поступка. Если же он вознамерился совершить благой поступок и совершил его, то Аллах запишет ему у Себя от десяти благодеяний до семисот, или даже многим более».</i></b> Аль-Бухари, 6491; Муслим, 131."],["p","[723] Сура «аль-Исра», аят 79."],["p","[724] Сура «Та Ха», аят 108."],["p","[725] Хафиз аль-Мунзири сказал: <i>«Этот хадис передали Ахмад, аль-Баззар, Абу Я′ля и Ибн Хиббан в «Сахихе», который сказал: «Сказал Исхак ибн Ибрахим: «Это — один из самых почетных хадисов!» Этот хадис передали от Пророка (да благословит его Аллах и приветствует) сразу несколько сподвижников, среди которых Хузейфа, Абу Мас′уд, Абу Хурейра и другие».</i>"],["p","[726] То есть: «Для меня этот день так же суров и долог, как и для вас». Возможен также и следующий перевод его фразы: <i>«Поистине, я так же совершил (в ближней жизни) грехи, как и вы!»</i> См. «Хашия Муснад Ахмад», 1/33—34, Абу-ль Хасана ас-Синди."],["p","[727] Этот хадис передали аль-Бухари и Муслим со слов Абу Хурейры (да будет доволен им Аллах)."],["p","[728] Всевышний Аллах сказал о пророке Нухе: <b>«Поистине, он был благодарным рабом».</b> (Сура «аль-Исра», аят 3)."],["p","[729] Сура «Нух», аят 26."],["p","[730] Сура «Нух», аят 26."],["p","[731] Всевышний Аллах сказал: <b>«О Муса! Поистине, Я избрал тебя среди людей посредством Своего послания и Своей речи. Бери же то, что Я даю тебе, и будь из числа благодарных!».</b> (Сура «аль-А′раф», аят 144)."],["p","[732] Сказал Ибн ′Аббас: <i>«Аллах назвал ′Ису (Своим) словом, так как он был сотворен посредством слова «Будь!».</i> См. «Аль-Муфхим», 1/435. Всевышний Аллах сказал: <b>« (Марьям) сказала: «Господь мой! Как у меня может быть ребенок, если меня не касался мужчина?!» (Джибриль) ответил (ей): «Именно так Аллах творит то, что пожелает! Когда Он (желает) совершить что-нибудь</b>"]],"notes":[]},{"n":352,"head":"МУХАММАД ИБН САЛИХ ИБН 'УСЕЙМИН","side":"c","blocks":[["c","<b>, то говорит ему: «Будь!» — и оно появляется».</b> (Сура «Али ′Имран», аят 47)."],["p","[733] Всевышний Аллах сказал: <b>«Поистине, Мы даровали тебе явную победу, чтобы простил тебе Аллах твои прошлые и будущие упущения, и завершил милость Свою по отношению к тебе, и направил тебя к прямому пути!»</b> (Сура «аль-Фатх», аяты 1—2)."],["p","[734] Есть несколько видов заступничества. 1 — <b>Общее великое заступничество</b> — этот вид заступничества не отрицает никто из тех, кто относит себя к Исламу. Это заступничество Пророка (да благословит его Аллах и приветствует), который будет заступаться перед Аллахом за людей и джиннов, чтобы начался Суд. Именно это и есть «достохвальное место», о котором сказано в словах Всевышнего: <b>«Быть может, Господь твой возведет тебя на достохвальное место».</b> (Сура «аль-Исра», аят 79). 2 — <b>Заступничество за обитателей Рая, чтобы они вошли в Рай,</b> — это также даровано только Пророку (да благословит его Аллах и приветствует). Он — первый, перед кем распахнутся райские врата, а его община войдет в Рай раньше остальных общин. Именно об этом Посланник Аллаха (да благословит его Ал-лах и приветствует) сказал: <b><i>«Мы — последние (по времени из общин), (но) в День воскресения (мы станем) первыми, (кто войдет в Рай)».</i></b> Аль-Бухари, 876; Муслим, 855. 3 — <b>Заступничество Пророка</b> (да благословит его Аллах и приветствует) <b>за своего дядю Абу Талиба</b> — чтобы тому было облегчено адское наказание. Абу Талиб умер неверующим и будет одним из обитателей Огня. Но дело в том, что он оказывал помощь Посланнику Аллаха (да благословит его Аллах и приветствует), пока был жив, хотя и не принял Ислам. Поэтому это заступничество касается только Абу Талиба. А остальным неверующим не поможет ничье заступничество, как сказал об этом Всевышний: <b>«Заступничество заступников не поможет им».</b> (Сура «аль-Муддассир», аят 48). Вместе с тем нужно заметить, что Абу Талиб не выйдет из Огня, ему просто будет облегчено адское наказание. Следующие виды заступничества дарованы не только Пророку (да благословит его"]],"notes":[]},{"n":353,"head":"УБЕЖДЕНИЯ ПРИВЕРЖЕНЦЕВ СУННЫ И ЕДИНОЙ ОБЩИНЫ","side":"c","blocks":[["c","Аллах и приветствует), но и другим пророкам, а также ангелам и праведным людям. 4 — <b>Заступничество за обитателей Рая, чтобы поднялась их степень в Раю.</b> 5 — <b>Заступничество за тех, кто заслуживает Огня, чтобы они вошли в Рай</b>. 6 — <b>Заступничество за тех, кто вошел в Огонь, чтобы они вышли из Огня</b>. Заступничество возможно только при наличии двух условий: 1 ― <b>Позволение Аллаха тому, кто заступается</b>. Аллах Всевышний сказал: <b>«Кто станет заступаться перед Ним без Его дозволения?»</b> (Сура «аль-Бакара», аят 255). Никто не сможет заступиться за кого-то, если этого не позволит Аллах Всевышний. 2 ― <b>Довольство Аллаха тем, за кого заступаются, а Аллах доволен только единобожниками</b>. Аллах Всевышний сказал: <b>«Заступничество заступников не поможет им</b> [неверующим]<b>».</b> (Сура «аль-Муддассир», аят 48). А также: <b>«Они</b> [ангелы] <b>заступаются только за тех, кем Он доволен, а сами трепещут от страха перед Ним».</b> (Сура «аль-Анбия», аят 28). Также в одном из аятов Аллах Всевышний упомянул сразу два этих условия, сказав: <b>«Сколько же на небесах ангелов, заступничество которых не принесет никакой пользы, пока Аллах не позволит заступиться за тех, за кого Он пожелает и кем Он доволен!»</b> (Сура «ан-Наджм», аят 26)."],["p","[735] Это указывает на то, что его длина равна его ширине. Иначе говоря, он представляет собой квадрат. А Аллах знает лучше! См. «Аль-Каукаб уль-уаххадж», 23/66. Этот хадис передали аль-Бухари и Муслим со слов ′Абдуллаха ибн ′Амра, да будет доволен Аллах им и его отцом."],["p","[736] Сказал аль-Куртуби: <i>«Са′дан — это растение, на котором много колючек. Его колючки подобны крюкам».</i> См. «Аль-Муфхим», 1/420."],["p","[737] Сура «аль-Муззаммиль», аят 17."],["p","[738] То есть с каждого будут взыскивать за то, что он обидел или как-либо притеснил другого."],["p","[739] Сура «аз-Зумар», аят 71."],["p","[740] Сура «аль-Анбия», аят 28."],["p","[741] Аль-Бухари, 6564; Муслим, 210, со слов Абу Са′ида аль-Худри (да будет доволен им Аллах)."]],"notes":[]},{"n":354,"head":"МУХАММАД ИБН САЛИХ ИБН 'УСЕЙМИН","side":"c","blocks":[["c","[742] Сура «ас-Саджда», аят 17."],["q","[743] Сура «Али ′Имран», аят 133."],["q","[744] Аль-Бухари, 3679; Муслим, 2394, со слов Джабира (да будет доволен им Аллах)."],["q","[745] Аль-Бухари, 3679; Муслим, 2457, со слов Джабира (да будет доволен им Аллах)."],["q","[746] Сура «Ибрахим», аят 23."],["q","[747] Сура «аль-Уакы′а», аяты 25—26."],["q","[748] Сура «ас-Саджда», аят 17."],["q","[749] Аль-Бухари, 3244; Муслим, 2824, со слов Абу Хурейры (да будет доволен им Аллах)."],["q","[750] Сура «аль-Кахф», аят 29."],["q","[751] То есть земной огонь."],["q","[752] Аль-Бухари, 3265; Муслим, 2843, со слов Абу Хурейры (да будет доволен им Аллах)."],["q","[753] Сура «ан-Ниса», аят 56."],["q","[754] Сура «аль-Кахф», аят 29."],["q","[755] Сура «аль-Бакара», аят 254."],["q","[756] Сура «аз-Зумар», аят 16."],["q","[757] Сура «Мухаммад», аят 15."],["q","[758] Сура «аль-Хаджж», аят 20."],["q","[759] Сура «ат-Таляк», аят 11."],["q","[760] Сура «аль-Ахзаб», аяты 64—66."],["q","[761] Сура «Али ′Имран», аят 133."],["q","[762] Сура «ат-Таляк», аят 11."],["q","[763] Сура «аль-Ахзаб», аяты 64—65."],["q","[764] Сура «аль-Ахзаб», аят 66."],["q","[765] Сура «Юнус», аяты 90—91."],["q","[766] Сура «аль-Ан′ам», аят 27."],["q","[767] Сура «аль-Ан′ам», аят 28."],["q","[768] Сура «аль-Лейль», аяты 17—21."],["q","[769] Передают со слов «Абд ур-Рахмана ибн «Ауфа и Са’ида ибн Зейда, что Посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Абу Бакр — в Раю, «Умар — в Раю,</i></b>"],["p","<b><i>«Усман — в Раю, «Али — в Раю, Тальха ибн «Убайдуллах — в Раю,</i></b>"]],"notes":[]},{"n":355,"head":"УБЕЖДЕНИЯ ПРИВЕРЖЕНЦЕВ СУННЫ И ЕДИНОЙ ОБЩИНЫ","side":"c","blocks":[["c","<b><i>аз-Зубайр ибн уль-«Аввам — в Раю, «Абд ур-Рахман ибн «Ауф — в Раю, Са’д ибн Аби Уаккас — в Раю, Са’ид ибн Зейд — в Раю и Абу «Убайда ибн уль-Джаррах — в Раю».</i></b> Ахмад, 1/188; ат-Тирмизи, 3747; Ибн Маджа, 132, и другие."],["p","[770] Сура «Али ′Имран», аят 133."],["p","[771] Аль-Бухари, 2898; Муслим, 112."],["p","[772] Аль-Бухари, 2898; Муслим, 112."],["p","[773] Аль-Бухари, 7405; Муслим, 2675, со слов Абу Хурейры (да будет доволен им Аллах)."],["p","[774] Сура «аль-Хашр», аят 10."],["p","[775] Аль-Бухари, 2803; Муслим, 1876, со слов Абу Хурейры (да будет доволен им Аллах)."],["p","[776] Аль-Бухари, 4269; Муслим, 96, со слов Усамы (да будет доволен им Аллах)."],["p","[777] Сура «аль-Масад», аяты 1—5."],["p","[778] Этот человек первым принес идолов на Аравийский полуостров после пророка Ибрахима."],["p","[779] Сура «Ибрахим», аят 27."],["p","[780] Сура «Ибрахим», аят 27."],["p","[781] Сура «ан-Нахль», аят 32."],["p","[782] Сура «ан-Нахль», аят 32."],["p","[783] Ахмад, 4/287; Абу Дауд, 4753, со слов аль-Бары (да будет доволен им Аллах). В этом хадисе сказано: <b><i>«Затем глашатай с небес провозглашает (слова Аллаха): „Мой раб сказал правду! Расстелите для него (ложе) из Рая, облачите его в райские (одеяния) и откройте для него (в могиле) дверь в Рай!“ И тогда к нему приходит благоухание и аромат Рая, и его могила расширяется для него на расстояние взора».</i></b>"],["p","[784] Сура «аль-Ан′ам», аят 93."],["p","[785] Сура «аль-Бакара», аят 254."],["p","[786] Сура «аль-Бакара», аят 3."],["p","[787] Здесь в первом издании книги заканчиваются комментарии шейха Ибн ′Усеймина, да помилует его Аллах. Именно поэтому далее мы приведем лишь текст самой книги с небольшими его комментариями из имеющихся на его официальном"]],"notes":[]},{"n":356,"head":"МУХАММАД ИБН САЛИХ ИБН 'УСЕЙМИН","side":"c","blocks":[["c","сайте аудио уроков."],["p","[788] Муслим, 8; Абу Дауд, 4695; ан-Насаи, 4990; Ахмад, 1/51; Ибн Хузейма, 2504; ат-Таялиси, 21; аль-Бейхакы в «Сунан аль-кубра», 10/203, со слов ′Умара ибн уль-Хаттаба. Также этот хадис передали аль-Бухари и Муслим со слов Абу Хурейры."],["p","[789] Сура «Та Ха», аят 51."],["p","[790] Сура «Та Ха», аят 51."],["p","[791] Сура «аль-Хаджж», аят 70."],["p","[792] Всевышний Аллах сказал: <b>«Но вы не пожелаете этого, если не пожелает Аллах, Господь миров».</b> (Сура «ат-Такуир», аят 29)."],["p","[793] Сура «аз-Зумар», аяты 62—63."],["p","[794] Сура «ат-Такуир», аяты 28—29."],["p","[795] Сура «аль-Бакара», аят 253."],["p","[796] Сура «аль-Ан′ам», аят 137."],["p","[797] Сура «ас-Саффат», аят 96."],["p","[798] Сура «аль-Бакара», аят 223."],["p","[799] Сура «ат-Тауба», аят 46."],["p","[800] Сура «аль-Бакара», аят 286."],["p","[801] Сура «ан-Ниса», аят 165."],["p","[802] Сура «Лукман», аят 34."],["p","[803] Сура «аль-Ан′ам», аят 148."],["p","[804] Муслим, 771, со слов ′Али ибн Аби Талиба (да будет доволен им Аллах)."],["p","[805] Абу Дауд, 1425; ат-Тирмизи, 464; ан-Насаи, 1745; Ибн Маджа, 1178, со слов аль-Хасана (да будет доволен им Аллах)."],["p","[806] Сура «ар-Рум», аят 41."],["p","[807] Сура «ан-Нахль», аят 97."],["p","[808] Сура «аль-Хадид», аяты 22—23."]],"notes":[]},{"blocks":[["p","<b>ОГЛАВЛЕНИЕ</b>",{"z":1.4}],["toc","Предисловие",{"mt":1.4,"pg":"3"}],["toc","Первое вступление шейха ибн ′Усеймина",{"pg":"6"}],["toc","Второе вступление шейха ибн ′Усеймина",{"pg":"8"}],["toc","Начало книги",{"pg":"12"}],["toc","Наши убеждения",{"pg":"35"}],["toc","Разъяснение аята «аль-Курсий»",{"pg":"43"}],["toc","Разъяснение аятов из суры «аль-Хашр»",{"pg":"63"}],["toc","Разъяснение аятов из суры «аш-Шура»[196]",{"pg":"78"}],["toc","Разъяснение 6-го аята из суры «Худ»",{"pg":"90"}],["toc","Разъяснение 59-го аята из суры «аль-Ан′Ам»",{"pg":"92"}],["toc","Разъяснение 34-го аята из суры «Лукман»",{"pg":"94"}],["toc","Речь Аллаха",{"pg":"99"}],["toc","Коран — это речь Аллаха",{"pg":"108"}],["toc","Возвышенность Аллаха",{"pg":"111"}],["toc","Аллах возвысился над троном",{"pg":"117"}],["toc","Сопутствие аллаха",{"pg":"124"}],["toc","Кто такие хулюлиты (пантеисты)?",{"pg":"127"}],["toc","Нисхождение Аллаха на ближнее небо",{"pg":"129"}],["toc","Приход Аллаха в Судный День",{"pg":"135"}],["toc","Желание Аллаха",{"pg":"139"}],["toc","Любовь Аллаха",{"pg":"147"}],["toc","Довольство и ненависть Аллаха",{"pg":"157"}],["toc","Гнев Аллаха",{"pg":"160"}],["toc","Лик Аллаха",{"pg":"162"}],["toc","Две руки Аллаха",{"pg":"163"}],["toc","Два глаза Аллаха",{"pg":"166"}],["toc","Лицезрение Аллаха",{"pg":"169"}],["toc","Аллах далек от недостатков и изъянов",{"pg":"176"}],["toc","Наша позиция в отношении атрибутов Аллаха",{"pg":"181"}],["toc","Вера в ангелов",{"pg":"195"}],["toc","Вера в Писания",{"pg":"211"}],["toc","Вера в посланников",{"pg":"223"}]],"notes":[]},{"blocks":[["toc","Сподвижники пророка (да благословит его Аллах и приветствует)",{"pg":"239"}],["toc","Вера в Судный День",{"pg":"254"}],["toc","Вера в предопределение[787]",{"pg":"288"}],["toc","Заключение",{"pg":"295"}],["toc","Примечания",{"pg":"298"}]],"notes":[]},{"blocks":[["h","Мухаммад ибн Салих ибн 'Усеймин",{"z":1.2}],["q","Убеждения приверженцев сунны и единой общины",{"z":1.2,"mt":2.26}],["p","Создано в интеллектуальной издательской системе Ridero",{"mt":6}]],"notes":[]}];
